    for (int i=1; i<=m; ++i) {
        for (int j=1; j<=i+1; ++j) {
            int temp= (long long)C[i-1][j-1]* (i+1)%mod;
            f[i]= (f[i]+ (long long)temp* (long long)f[j-1]%mod* f[i-j]%mod)%mod;
            int t1= (long long)C[i-1][j-1]* (i+1)%mod;
