            g[i]= (g[i]+ (long long)t1* (long long)t2)%mod;
            int add= (long long)C[i-1][j-1]* ((j-1)*j/2 + (i-j+1)*(i-j)/2)%mod;
            g[i]= (g[i]+ (long long)add* (long long)f[j-1]*f[i-j]%mod)%mod;
        }
    }
    n++;
    memset(dp,0,sizeof(dp));
    memset(dp2,0,sizeof(dp2));
    dp[0][0]=1; dp2[0][0]=0;
    for (int i=0; i<=n; ++i) {
        for (int j=0; j<=m; ++j) {
            for (int k=0; j+k<=m && i+k+1<=n; ++k) {
                int c= C[j+k][j];
                long long val1= (long long)dp[i][j]*f[k]%mod;
                long long val2= (long long)dp2[i][j]*c%mod;
                long long val3= (long long)dp[i][j]*g[k]%mod;
                long long sum2= (val2 + val3)%mod;
                long long new_dp= (long long)dp[i][j]*f[k]%mod * c%mod;
                long long new_dp2= (val2 + val3)%mod * c%mod;
                dp[i+k+1][j+k]= (dp[i+k+1][j+k]+ new_dp)%mod;
                dp2[i+k+1][j+k]= (dp2[i+k+1][j+k]+ new_dp2)%mod;
            }
